sys_script_client.script:
function onLoad() {

    g_form.setDisplay('ops_investigation_result',false);
	g_form.setDisplay('ops_review_outcome',false);

    var existingValue = g_form.getValue('outcome');
	var shortDescription = g_form.getValue('short_description');

    g_form.clearOptions('outcome'); //Clear all options from the Outcome Field
	g_form.addOption('outcome', '', '-- None --'); //Add None back in
	if (existingValue) g_form.setValue('outcome', existingValue);

	var ga = new GlideAjax('HSBCTradeCaseUtils'); // 
    ga.addParam('sysparm_name', 'getOutcomesOptions');
    ga.addParam('sysparm_short_description', shortDescription);

    var outcomesString = ga.getXMLAnswer(outcomesParse);




}

// callback function for returning the result from the script include
function outcomesParse(response) {

    var outcomesArr = response.replace(/^"(.*)"$/, '$1').split(',');

    for (var i = 0; i < outcomesArr.length; i++) {
        g_form.addOption('outcome', outcomesArr[i], outcomesArr[i]);
    }


}
